'use client';

import { useState, FormEvent, ChangeEvent } from 'react';
import { useAuth } from '@/context/AuthContext';
import { useRouter } from 'next/navigation';
import api from '@/lib/api';

interface FormState {
  title: string;
  description: string;
  image_url: string;
  start_price: string;
  end_at: string;
}

export default function CreateAuctionPage() {
  const { user, loading } = useAuth();
  const router = useRouter();

  const [form, setForm] = useState<FormState>({
    title: '',
    description: '',
    image_url: '',
    start_price: '',
    end_at: '',
  });
  const [error, setError]       = useState('');
  const [submitting, setSubmitting] = useState(false);

  if (loading) return null;
  if (!user) {
    router.replace('/login');
    return null;
  }

  const set = (field: keyof FormState) => (
    e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => setForm(prev => ({ ...prev, [field]: e.target.value }));

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError('');
    try {
      setSubmitting(true);
      const res = await api.post('/auctions', {
        title:       form.title,
        description: form.description || null,
        image_url:   form.image_url || null,
        start_price: parseFloat(form.start_price),
        end_at:      form.end_at,
      });
      router.push(`/auctions/${res.data.id}`);
    } catch (err: unknown) {
      const msg =
        (err as { response?: { data?: { message?: string } } })?.response?.data?.message ??
        'Impossible de créer l\'enchère.';
      setError(msg);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto bg-white rounded-2xl shadow p-8">
      <h1 className="text-2xl font-bold text-gray-900 mb-6">Créer une enchère</h1>

      <form onSubmit={handleSubmit} className="space-y-5">
        <Field label="Titre" required>
          <input
            type="text"
            value={form.title}
            onChange={set('title')}
            required
            className={inputCls}
          />
        </Field>

        <Field label="Description">
          <textarea
            value={form.description}
            onChange={set('description')}
            rows={3}
            className={inputCls}
          />
        </Field>

        <Field label="URL de l'image">
          <input
            type="url"
            value={form.image_url}
            onChange={set('image_url')}
            className={inputCls}
          />
        </Field>

        <Field label="Prix de départ (€)" required>
          <input
            type="number"
            step="0.01"
            min="0.01"
            value={form.start_price}
            onChange={set('start_price')}
            required
            className={inputCls}
          />
        </Field>

        <Field label="Date et heure de fin" required>
          <input
            type="datetime-local"
            value={form.end_at}
            onChange={set('end_at')}
            required
            className={inputCls}
          />
        </Field>

        {error && <p className="text-red-500 text-sm">{error}</p>}

        <button
          type="submit"
          disabled={submitting}
          className="w-full bg-indigo-600 text-white py-2 rounded-lg font-medium hover:bg-indigo-700 disabled:opacity-50 transition-colors"
        >
          {submitting ? 'Création...' : 'Créer l\'enchère'}
        </button>
      </form>
    </div>
  );
}

const inputCls =
  'w-full border border-gray-300 rounded-lg px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500';

function Field({
  label,
  required,
  children,
}: {
  label: string;
  required?: boolean;
  children: React.ReactNode;
}) {
  return (
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-1">
        {label}
        {required && <span className="text-red-500 ml-0.5">*</span>}
      </label>
      {children}
    </div>
  );
}
